(ROOT/"combined_refactor/proxy_geo.go").write_text('package main\n\nimport (\n    "context"\n    "encoding/json"\n    "io"\n    "net"\n    "net/http"\n    "net/url"\n    "strings"\n    "sync"\n    "time"\n)\n\ntype proxyGeoPayload struct {\n    Success     bool   `json:"success"`\n    Message     string `json:"message"`\n    CountryCode string `json:"country_code"`\n    Country     string `json:"country"`\n    Region      string `json:"region"`\n    City        string `json:"city"`\n}\n\nvar proxyGeoCache sync.Map\nvar proxyGeoSem = make(chan struct{}, 2)\nvar proxyGeoClient = &http.Client{\n    Timeout: 5 * time.Second,\n    Transport: &http.Transport{\n        MaxIdleConns:        4,\n        MaxIdleConnsPerHost: 2,\n        IdleConnTimeout:     30 * time.Second,\n        DisableCompression:  true,\n    },\n}\n\nvar proxyCountryZH = map[string]string{\n    "HK": "香港", "MO": "澳门", "TW": "台湾", "CN": "中国大陆",\n    "JP": "日本", "KR": "韩国", "SG": "新加坡", "US": "美国",\n    "DE": "德国", "IE": "爱尔兰", "GB": "英国", "FR": "法国",\n    "NL": "荷兰", "CA": "加拿大", "AU": "澳大利亚", "CL": "智利",\n    "BR": "巴西", "IN": "印度", "ID": "印度尼西亚", "MY": "马来西亚",\n    "TH": "泰国", "VN": "越南", "PH": "菲律宾", "RU": "俄罗斯",\n    "SE": "瑞典", "FI": "芬兰", "NO": "挪威", "DK": "丹麦",\n    "CH": "瑞士", "AT": "奥地利", "IT": "意大利", "ES": "西班牙",\n    "PL": "波兰", "CZ": "捷克", "RO": "罗马尼亚", "TR": "土耳其",\n    "AE": "阿联酋", "ZA": "南非", "MX": "墨西哥", "AR": "阿根廷",\n}\n\nfunc proxyCountryLabel(code string) string {\n    code = strings.ToUpper(strings.TrimSpace(code))\n    if code == "" {\n        return ""\n    }\n    if name := proxyCountryZH[code]; name != "" {\n        return name + "（" + code + "）"\n    }\n    return code\n}\n\nfunc proxyGeoLabel(data proxyGeoPayload) string {\n    code := strings.ToUpper(strings.TrimSpace(data.CountryCode))\n    country := proxyCountryZH[code]\n    if country == "" {\n        country = strings.TrimSpace(data.Country)\n    }\n    if country == "" {\n        country = code\n    }\n    city := strings.TrimSpace(data.City)\n    if city == "" {\n        city = strings.TrimSpace(data.Region)\n    }\n    if country == "" {\n        return city\n    }\n    if city != "" && !strings.EqualFold(city, country) {\n        return country + " · " + city\n    }\n    if code != "" && country != code {\n        return country + "（" + code + "）"\n    }\n    return country\n}\n\nfunc lookupProxyGeo(ctx context.Context, ip string) string {\n    ip = strings.TrimSpace(ip)\n    parsed := net.ParseIP(ip)\n    if parsed == nil || parsed.IsLoopback() || parsed.IsPrivate() || parsed.IsUnspecified() {\n        return ""\n    }\n    if cached, ok := proxyGeoCache.Load(ip); ok {\n        return cached.(string)\n    }\n    select {\n    case proxyGeoSem <- struct{}{}:\n        defer func() { <-proxyGeoSem }()\n    case <-ctx.Done():\n        return ""\n    }\n    if cached, ok := proxyGeoCache.Load(ip); ok {\n        return cached.(string)\n    }\n    endpoint := "https://ipwho.is/" + url.PathEscape(ip)\n    req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)\n    if err != nil {\n        return ""\n    }\n    req.Header.Set("User-Agent", "CF-IP-Selector/1.0")\n    resp, err := proxyGeoClient.Do(req)\n    if err != nil {\n        return ""\n    }\n    defer resp.Body.Close()\n    if resp.StatusCode < 200 || resp.StatusCode >= 300 {\n        return ""\n    }\n    raw, err := io.ReadAll(io.LimitReader(resp.Body, 64*1024))\n    if err != nil {\n        return ""\n    }\n    var data proxyGeoPayload\n    if json.Unmarshal(raw, &data) != nil || !data.Success {\n        return ""\n    }\n    label := proxyGeoLabel(data)\n    if label != "" {\n        proxyGeoCache.Store(ip, label)\n    }\n    return label\n}\n\nfunc enrichProxyLocation(ctx context.Context, result *proxyLocalResult) {\n    if result == nil {\n        return\n    }\n    if code := strings.TrimSpace(result.Loc); code != "" {\n        result.Location = proxyCountryLabel(code)\n        result.LocationSource = "出口"\n        return\n    }\n    // Keep the main scan lightweight: only query external GeoIP when an eligible row has no trace location.\n    if result.Status != "success" {\n        return\n    }\n    if result.ExitIP != "" {\n        if label := lookupProxyGeo(ctx, result.ExitIP); label != "" {\n            result.Location = label\n            result.LocationSource = "出口"\n            return\n        }\n    }\n    if label := lookupProxyGeo(ctx, result.IP); label != "" {\n        result.Location = label\n        result.LocationSource = "入口（出口未知）"\n    }\n}\n',encoding="utf-8")

p=ROOT/"combined_refactor/tasks_nsb.go"
s=p.read_text(encoding="utf-8")
pattern=r"func runNSBDownloadSpeed\(ctx context\.Context, ip string, port int, enableTLS bool, testURL string\) \(float64, string\) \{.*?\n\}\n\nfunc runNSBTask"
new='func runNSBDownloadSpeed(ctx context.Context, ip string, port int, enableTLS bool, testURL string) (float64, string) {\n\tconst speedWindow = 5 * time.Second\n\tconst speedMaxBytes int64 = 32 * 1024 * 1024\n\tconst speedBufferSize = 256 * 1024\n\n\tscheme := "http"\n\tif enableTLS {\n\t\tscheme = "https"\n\t}\n\n\tparsedURL, err := parseSpeedTestURL(testURL, scheme)\n\tif err != nil {\n\t\treturn 0, "测速地址解析失败: " + err.Error()\n\t}\n\n\ttransport := &http.Transport{\n\t\tDialContext: func(c context.Context, network, addr string) (net.Conn, error) {\n\t\t\treturn dialContextWithTimeout(c, "tcp", net.JoinHostPort(ip, strconv.Itoa(port)), 4*time.Second)\n\t\t},\n\t\tTLSHandshakeTimeout: 5 * time.Second,\n\t\tTLSClientConfig:     tlsConfigWithRootCAs(parsedURL.Hostname()),\n\t\tDisableCompression:  true,\n\t\tDisableKeepAlives:   true,\n\t\tForceAttemptHTTP2:   false,\n\t\tMaxIdleConns:        1,\n\t\tMaxIdleConnsPerHost: 1,\n\t}\n\tdefer transport.CloseIdleConnections()\n\n\tspeedCtx, cancel := context.WithTimeout(ctx, speedWindow)\n\tdefer cancel()\n\treq, err := http.NewRequestWithContext(speedCtx, "GET", parsedURL.String(), nil)\n\tif err != nil {\n\t\treturn 0, "测速请求构建失败: " + err.Error()\n\t}\n\treq.Host = parsedURL.Host\n\treq.Header.Set("User-Agent", "Mozilla/5.0")\n\treq.Header.Set("Accept-Encoding", "identity")\n\n\tclient := http.Client{Transport: transport}\n\tresp, err := client.Do(req)\n\tif err != nil {\n\t\tif ctx.Err() != nil {\n\t\t\treturn 0, "测速任务已终止"\n\t\t}\n\t\treturn 0, "测速请求失败: " + err.Error()\n\t}\n\tdefer resp.Body.Close()\n\tif resp.StatusCode < http.StatusOK || resp.StatusCode >= http.StatusMultipleChoices {\n\t\t_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 4096))\n\t\treturn 0, formatSpeedHTTPFailure(resp.StatusCode)\n\t}\n\n\tstart := time.Now()\n\tbuf := make([]byte, speedBufferSize)\n\twritten, readErr := io.CopyBuffer(io.Discard, io.LimitReader(resp.Body, speedMaxBytes), buf)\n\tduration := time.Since(start)\n\tif ctx.Err() != nil {\n\t\treturn 0, "测速任务已终止"\n\t}\n\tif written <= 0 || duration <= 0 {\n\t\treturn 0, "测速未收到有效下载数据"\n\t}\n\tif readErr != nil && speedCtx.Err() == nil && readErr != io.EOF {\n\t\treturn 0, "测速下载失败: " + readErr.Error()\n\t}\n\treturn float64(written) / duration.Seconds() / 1024, ""\n}\n\nfunc runNSBTask'
s2,n=re.subn(pattern,new,s,count=1,flags=re.S)
if n!=1: raise SystemExit(f"runNSBDownloadSpeed replace count={n}")
p.write_text(s2,encoding="utf-8")

